65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final AddressNormalizer addressNormalizer;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper,
88	                                 TelephoneNormalizer telephoneNormalizer,
89	                                 AddressNormalizer addressNormalizer) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	        this.telephoneNormalizer = telephoneNormalizer;
95	        this.addressNormalizer = addressNormalizer;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
122	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
129	        rejectBlankOwnerFields(ownerFieldsDto);
130	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
131	        if (!sharesHousehold) {
132	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
133	        }
134	        rejectCityAtCapacity(ownerFieldsDto.getCity());
135	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
136	        rejectDailyRegistrationLimit(registrationDate);
137	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
138	        rejectDuplicateTelephone(normalizedTelephone);
139	        ownerFieldsDto.setTelephone(normalizedTelephone);
140	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        owner.setRegistrationDate(registrationDate);
144	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
145	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
146	        if (sharesHousehold) {
147	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
148	        }
149	        this.clinicService.saveOwner(owner);
150	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
151	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
152	            ownerMapper.membershipLevel(owner));
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
163	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
164	        if (currentOwner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        currentOwner.setAddress(ownerFieldsDto.getAddress());
168	        currentOwner.setCity(ownerFieldsDto.getCity());
169	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
170	        currentOwner.setLastName(ownerFieldsDto.getLastName());
171	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
172	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
173	        this.clinicService.saveOwner(currentOwner);
174	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Transactional
179	    @Override
180	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        this.clinicService.deleteOwner(owner);
186	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
192	        Owner owner = this.clinicService.findOwnerById(ownerId);
193	        if (owner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        HttpHeaders headers = new HttpHeaders();
197	        Pet pet = petMapper.toPet(petFieldsDto);
198	        owner.setId(ownerId);
199	        pet.setOwner(owner);
200	        pet.getType().setName(null);
201	        this.clinicService.savePet(pet);
202	        PetDto petDto = petMapper.toPetDto(pet);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
204	            .buildAndExpand(pet.getId()).toUri());
205	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
211	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
212	        if (currentOwner != null) {
213	            Pet currentPet = this.clinicService.findPetById(petId);
214	            if (currentPet != null) {
215	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
216	                currentPet.setName(petFieldsDto.getName());
217	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
218	                this.clinicService.savePet(currentPet);
219	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
220	            }
221	        }
222	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	    }
