240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
244	        Owner owner = this.clinicService.findOwnerById(ownerId);
245	        if (owner != null) {
246	            Pet pet = owner.getPet(petId);
247	            if (pet != null) {
248	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
249	            }
250	        }
251	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	    }
253	
254	    /**
255	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
256	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
257	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
258	     * blank (e.g. {@code "   "}). The offending field names are reported through an
259	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
260	     * as a 400 response carrying an {@code errors} array of field names.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields
263	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
264	     */
265	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
266	        List<String> blankFields = new ArrayList<>();
267	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
268	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
269	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
270	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
271	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
272	        if (!blankFields.isEmpty()) {
273	            throw new InvalidOwnerFieldsException(blankFields);
274	        }
275	    }
276	
277	    private void addIfBlank(List<String> blankFields, String field, String value) {
278	        if (value != null && value.isBlank()) {
279	            blankFields.add(field);
280	        }
281	    }
282	
283	    /**
284	     * Normalizes an owner's optional email address. When present it is stored and returned
285	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
286	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
287	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
288	     * method runs.
289	     *
290	     * @param email the raw email value from the request, or {@code null} when omitted
291	     * @return the lower-cased email, or {@code null} when none was supplied
292	     */
293	    private String normalizeEmail(String email) {
294	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
295	    }
296	
297	    /**
298	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
299	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
300	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
301	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
302	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
303	     *
304	     * @param city the city of the owner being created
305	     * @param lastName the last name of the owner being created
306	     * @return the formatted customer code
307	     */
308	    private String nextCustomerCode(String city, String lastName) {
309	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
310	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
311	        long sequence = this.clinicService.findAllOwners().stream()
312	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
313	            .count() + 1L;
314	        return String.format("%s-%s-%04d", city3, last3, sequence);
315	    }
316	
317	    /**
318	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
319	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
320	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
321	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
322	     * new owner and surfaced as the read-only {@code namesakeCount} field.
323	     *
324	     * @param firstName the first name of the owner being created
325	     * @param lastName the last name of the owner being created
326	     * @return the number of existing owners with the same first and last name (case-insensitive)
327	     */
328	    private int namesakeCount(String firstName, String lastName) {
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
331	                && equalsIgnoreCase(owner.getLastName(), lastName))
332	            .count();
333	    }
334	
335	    private boolean equalsIgnoreCase(String a, String b) {
336	        return a == null ? b == null : a.equalsIgnoreCase(b);
337	    }
338	
339	    /**
340	     * The maximum number of owners a single city may contain. Once a city already holds this many
341	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
342	     */
343	    private static final long MAX_OWNERS_PER_CITY = 50L;
344	
345	    /**
346	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
347	     * owners. Existing owners are matched to the requested city case-insensitively (using
348	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
349	     * the per-city counting used for the customer code. A city at capacity is reported through an
350	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
351	     * 409 Conflict response.
352	     *
353	     * @param city the city of the owner being created
354	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
355	     */
356	    private void rejectCityAtCapacity(String city) {
357	        long owners = this.clinicService.findAllOwners().stream()
358	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
359	            .count();
360	        if (owners >= MAX_OWNERS_PER_CITY) {
361	            throw new OwnerCityAtCapacityException(city);
362	        }
363	    }
364	
365	    /**
366	     * The maximum number of owners that may be registered on a single day. Once this many owners
367	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
368	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
369	     */
370	    private static final long MAX_OWNERS_PER_DAY = 100L;
371	
372	    /**
373	     * Resolves the effective registration date for a create request: the value supplied in the
374	     * request when present, otherwise the server's current date. The result is the raw effective
375	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
376	     *
377	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
378	     * @return the supplied date, or today when none was supplied
379	     */
380	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
381	        return suppliedDate != null ? suppliedDate : LocalDate.now();
382	    }
383	
384	    /**
385	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
386	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
387	     * the effective registration date so that a weekend value - whether supplied in the request or
388	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
389	     * registration date (such as the membership number's year segment and the daily create-limit
390	     * bucket) uses the adjusted business day.
391	     *
392	     * @param date the effective registration date
393	     * @return the same date when it is a weekday, otherwise the next Monday
394	     */
395	    private LocalDate businessDay(LocalDate date) {
396	        DayOfWeek dayOfWeek = date.getDayOfWeek();
397	        if (dayOfWeek == DayOfWeek.SATURDAY) {
398	            return date.plusDays(2);
399	        }
400	        if (dayOfWeek == DayOfWeek.SUNDAY) {
401	            return date.plusDays(1);
402	        }
403	        return date;
404	    }
405	
406	    /**
407	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
408	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
409	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
410	     * renders as a 429 Too Many Requests response.
411	     *
412	     * @param date the registration date of the owner being created (today)
413	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
414	     */
415	    private void rejectDailyRegistrationLimit(LocalDate date) {
416	        long owners = this.clinicService.findAllOwners().stream()
417	            .filter(owner -> date.equals(owner.getRegistrationDate()))
418	            .count();
419	        if (owners >= MAX_OWNERS_PER_DAY) {
420	            throw new DailyOwnerRegistrationLimitException(date);
421	        }
422	    }
423	
424	    /**
425	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
426	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
427	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
428	     */
429	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
430	
431	    /**
432	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
433	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
434	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
435	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
436	     * without a registration date, such as seed data) is never flagged.
437	     *
438	     * @param date the owner's registration date (the day it was created), or {@code null}
439	     * @return {@code true} if the day already holds more than the warning threshold of owners
440	     */
441	    private boolean bulkSignupWarning(LocalDate date) {
442	        if (date == null) {
443	            return false;
444	        }
445	        long owners = this.clinicService.findAllOwners().stream()
446	            .filter(owner -> date.equals(owner.getRegistrationDate()))
447	            .count();
448	        return owners > BULK_SIGNUP_WARNING_THRESHOLD;
449	    }
450	
451	    /**
452	     * Rejects a create request whose normalized telephone is already used by any existing owner.
453	     * Existing owners' telephones are reduced to the same canonical form (via
454	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
455	     * only in formatting still collide. A collision is reported through a
456	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
457	     * as a 409 Conflict response.
458	     *
459	     * @param normalizedTelephone the canonical telephone of the owner being created
460	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
461	     */
462	    private void rejectDuplicateTelephone(String normalizedTelephone) {
463	        boolean duplicate = existingOwnerMatches(
464	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
465	            normalizedTelephone);
466	        if (duplicate) {
467	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
468	        }
469	    }
470	
471	    /**
472	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
473	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
474	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
475	     * and the owner being created to the same canonical key and reject a match.
476	     *
477	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
478	     * @param key the canonical key of the owner being created
479	     * @return {@code true} if some existing owner shares the key
480	     */
481	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
482	        return this.clinicService.findAllOwners().stream()
483	            .map(keyExtractor)
484	            .filter(Objects::nonNull)
485	            .anyMatch(key::equals);
486	    }
487	
488	    /**
489	     * Rejects a create request that shares a household with an existing owner: another owner already
490	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
491	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
492	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
493	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
494	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
495	     * check when the request opts in via {@code sharesHousehold}.
496	     *
497	     * @param lastName the last name of the owner being created
498	     * @param address the address of the owner being created
499	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
500	     */
501	    private void rejectDuplicateHousehold(String lastName, String address) {
502	        String canonicalLastName = canonicalizeHousehold(lastName);
503	        String canonicalAddress = canonicalizeHousehold(address);
504	        if (canonicalLastName == null || canonicalAddress == null) {
505	            return;
506	        }
507	        boolean duplicate = this.clinicService.findAllOwners().stream()
508	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
509	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
510	        if (duplicate) {
511	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
512	        }
513	    }
514	
515	    /**
516	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
517	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
518	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
519	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
520	     *
521	     * @param value the raw field value, or {@code null}
522	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
523	     */
524	    private String canonicalizeHousehold(String value) {
525	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
526	    }
527	
528	    /**
529	     * Derives the stable, shared {@code householdId} for an owner joining a household via
530	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
531	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
532	     * owner with the same last name at the same address - regardless of casing or spacing - is
533	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
534	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
535	     *
536	     * @param lastName the last name of the owner being created
537	     * @param address the address of the owner being created
538	     * @return the shared household identifier
539	     */
540	    private String householdId(String lastName, String address) {
541	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
542	        try {
543	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
544	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
545	            StringBuilder sb = new StringBuilder(digest.length * 2);
546	            for (byte b : digest) {
547	                sb.append(String.format("%02X", b));
548	            }
549	            return sb.substring(0, 16);
550	        } catch (java.security.NoSuchAlgorithmException e) {
551	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
552	        }
553	    }
554	}
